    "chat.tools.terminal.ignoreDefaultAutoApproveRules": {
      type: "boolean",
      default: false,
      tags: ["experimental"],
      markdownDescription:
        "Whether to ignore the built-in default auto-approve rules used by the run in terminal tool as defined in `#chat.tools.terminal.autoApprove#`. When this setting is enabled, the run in terminal tool will ignore any rule that comes from the default set but still follow rules defined in the user, remote and workspace settings. Use this setting at your own risk; the default auto-approve rules are designed to protect you against running dangerous commands.",
      section: { id: "terminal", title: "Integrated Terminal", order: 100 },
      defaultDefaultValue: false,
      scope: 4,
      restricted: false,
    },
    "chat.tools.terminal.autoApproveWorkspaceNpmScripts": {
      restricted: true,
      type: "boolean",
      default: true,
      tags: ["experimental"],
      markdownDescription:
        "Whether to automatically approve npm, yarn, and pnpm run commands when the script is defined in a workspace package.json file. Since the workspace is trusted, scripts defined in package.json are considered safe to run without explicit approval.",
      section: { id: "terminal", title: "Integrated Terminal", order: 100 },
      defaultDefaultValue: true,
      scope: 4,
    },
    "chat.tools.terminal.blockDetectedFileWrites": {
      type: "string",
      enum: ["never", "outsideWorkspace", "all"],
      enumDescriptions: [
        "Allow all detected file writes.",
        "Block file writes detected outside the workspace. This depends on the shell integration feature working correctly to determine the current working directory of the terminal.",
        "Block all detected file writes.",
      ],
      default: "outsideWorkspace",
      tags: ["experimental"],
      markdownDescription:
        "Controls whether detected file write operations are blocked in the run in terminal tool. When detected, this will require explicit approval regardless of whether the command would normally be auto approved. Note that this cannot detect all possible methods of writing files, this is what is currently detected:\n\n- File redirection (detected via the bash or PowerShell tree sitter grammar)\n- `sed` in-place editing (`-i`, `-I`, `--in-place`)",
      section: { id: "terminal", title: "Integrated Terminal", order: 100 },
      defaultDefaultValue: "outsideWorkspace",
      scope: 4,
      restricted: false,
    },
    "chat.tools.terminal.shellIntegrationTimeout": {
      markdownDescription:
        "Configures the duration in milliseconds to wait for shell integration to be detected when the run in terminal tool launches a new terminal. Set to `0` to skip the wait entirely, the default value `-1` uses a variable wait time based on the value of `#terminal.integrated.shellIntegration.enabled#` and whether it's a remote window. A large value can be useful if your shell starts very slowly.",
      type: "integer",
      minimum: -1,
      maximum: 60000,
      default: -1,
      markdownDeprecationMessage: "Use `#terminal.integrated.shellIntegration.timeout#` instead",
      section: { id: "terminal", title: "Integrated Terminal", order: 100 },
      defaultDefaultValue: -1,
      scope: 4,
      restricted: false,
      deprecationMessage: "Use terminal.integrated.shellIntegration.timeout instead",
    },
    "chat.tools.terminal.idlePollInterval": {
      markdownDescription:
        "Configures the idle poll interval in milliseconds used by the run in terminal tool to detect when commands have finished executing. Lower values make command detection faster but may cause false positives on slow systems. This primarily affects terminals without shell integration where idle detection is used instead of shell integration events.",
      type: "integer",
      minimum: 50,
      maximum: 10000,
      default: 1000,
      section: { id: "terminal", title: "Integrated Terminal", order: 100 },
      defaultDefaultValue: 1000,
      scope: 4,
      restricted: false,
    },
